1797	static bool road_ring_is_area(const vmap_point_t * pts, int32_t n)
1798	{
1799	    int32_t i;
1800	    int32_t dx;
1801	    int32_t dy;
1802	    double area2;
1803	    double peri;
1804	    double compactness;
1805	    double mean_w;
1806	
1807	    if (!pts || n < 5) {
1808	        return false;
1809	    }
1810	
1811	    dx = pts[0].x - pts[n - 1].x;
1812	    dy = pts[0].y - pts[n - 1].y;
1813	    if (dx * dx + dy * dy > 16) {
1814	        return false;
1815	    }
1816	
1817	    area2 = 0.0;
1818	    peri = 0.0;
1819	    for (i = 0; i < n - 1; i++) {
1820	        area2 += (double)pts[i].x * (double)pts[i + 1].y
1821	            - (double)pts[i + 1].x * (double)pts[i].y;
1822	        peri += hypot((double)(pts[i + 1].x - pts[i].x),
1823	            (double)(pts[i + 1].y - pts[i].y));
1824	    }
1825	
1826	    area2 = fabs(area2);
1827	    if (peri < 8.0) {
1828	        return false;
1829	    }
1830	
1831	    compactness = (2.0 * M_PI * area2) / (peri * peri);
1832	    mean_w = area2 / peri;
1833	    if (compactness > 0.55) {
1834	        return false;
1835	    }
1836	
1837	    return mean_w > 10.0 && compactness < 0.45;
1838	}
