void vmap_render_clear(vmap_canvas_t * c, uint16_t color)
{
    vmap_blit_surface_t surf;

    if (!c || !c->buf) {
        return;
    }

    /* 先问搬运后端（走 EPIC 时是一整块矩形一条命令）；它不可用或没通过自检
     * 时，同一个调用会把 CPU 版本做完 —— 见 vmap_blit.h。 */
    render_surface(c, &surf);
