    int32_t copy_h;
    int32_t x0;
    int32_t y0;

    if (!c || !c->buf) {
        return;
    }

    if (dx == 0 && dy == 0) {
        return;
    }

    if (dx >= c->w || dx <= -c->w || dy >= c->h || dy <= -c->h) {
        vmap_render_clear(c, fill);
        return;
    }

