/**
 * @file myvendor_system_font.h
 * @brief 板级系统矢量字体（TTF 预载 PSRAM，FreeType 光栅）。
 *
 * 开启 MYVENDOR_SYSTEM_VECTOR_FONT 时链进 liblvgl。
