bool myvendor_system_font_lv_bind(void)
{
#if !MYVENDOR_USE_VECTOR_FONT
    return false;
#else
    if (s_lv_bound) {
        return myvendor_system_font_preloaded();
    }

    if (!lv_is_initialized()) {
