void vmap_view_set_scale(vmap_view_t * view, double scale)
{
    if (!view) {
        return;
    }
    if (scale < 0.25) {
        scale = 0.25;
    } else if (scale > 8.0) {
        scale = 8.0;
    }
    view->scale = scale;
}

