                lv_obj_set_style_text_font(view->rot_label[i], font, 0);
            }
        }
    }
}

static double vmap_clamp_d(double v, double lo, double hi)
{
    if (v < lo) {
        return lo;
    }
    if (v > hi) {
        return hi;
    }
    return v;
}

