static bool boxes_overlap(const lv_area_t * a, const lv_area_t * b,
    int32_t gap_x, int32_t gap_y)
{
    return a->x1 - gap_x <= b->x2 && a->x2 + gap_x >= b->x1
        && a->y1 - gap_y <= b->y2 && a->y2 + gap_y >= b->y1;
}

